local UIActivityTotalTopupPanel = Class("UIActivityTotalTopupPanel")

function UIActivityTotalTopupPanel:__init()
    self.totalTopUpHomeData = nil
end

function UIActivityTotalTopupPanel:__delete()
    self.controller = nil
end

function UIActivityTotalTopupPanel:Awake()
    self:InitBindEvent()
end

function UIActivityTotalTopupPanel:OnDestroy()
    self.controller = nil --删除lua层引⽤用到的c#对象,否则不不会产⽣生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
------------------------------------------------------- public
function UIActivityTotalTopupPanel:SortData()
    table.sort(self:GetAccumulativePay(), function(a, b)
        local aStatus = checkInt(a.status)
        local bStatus = checkInt(b.status)
        if aStatus ~= bStatus then
            if aStatus == Constants.GetStatus.Can or bStatus == Constants.GetStatus.Can then
                return aStatus == Constants.GetStatus.Can
            else
                return aStatus < bStatus
            end
        else
            return checkInt(a.id) < checkInt(b.id)
        end
    end)
end
------------------------------------------------------- public
---@param activityDojo ActivityDojo
function UIActivityTotalTopupPanel:Refresh(activityDojo)
    self.activityDt   = activityDojo
    CfUtils.FillWebRawImage(self.Image.gameObject ,activityDojo.titleImage)
    GameUtils.Request(Interfaces.ActivityAccumulativePay, {activityUuid = activityDojo.id},
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    self.totalTopUpHomeData = response.data
                    self:SortData()
                    self:InitView()
                    self:UpdateRedPoint()
                end
            end
    )
end
function UIActivityTotalTopupPanel:GetCanIdMap()
    local data = {}
    local amount = checkInt(self:GetPlayerAmount()) 
    for k, v in pairs(self:GetAccumulativePay()) do
        if checkInt(v.status) == Constants.GetStatus.Can and amount >= checkInt(v.amount) then
            data[#data+1] = v.id 
        end
    end
    return data
end


function UIActivityTotalTopupPanel:GetPlayerAmount()
    return self.totalTopUpHomeData.playerAmount
end

function UIActivityTotalTopupPanel:InitBindEvent()
    SetButtonAction(self.FontStyleButton, function ()
        local data = self:GetCanIdMap() 
        local count = #data
        if count == 0 then
            GameUtils.Toast(localize("暂无可领取的奖励"))
            return 
        end
        self:OnDrawRewards()
    end)
end

function UIActivityTotalTopupPanel:InitView()
    -- update reward
    self:RefreshReward()

    -- update view
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self.activityDt.startTime, self.activityDt.endTime))
    CfUtils.FillText(self.Text, self.activityDt.detail)
end

function UIActivityTotalTopupPanel:RefreshReward()
    if not self.LoopListCell.IsListViewInit then
        self.LoopListCell:InitListView(#self:GetAccumulativePay(), Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListCell,#self:GetAccumulativePay())
    end
end

function UIActivityTotalTopupPanel:GetAccumulativePay()
    return self.totalTopUpHomeData.accumulativePay
end

----------------------------------------------------------------------------- handler

function UIActivityTotalTopupPanel:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cellNode = listView:NewListViewItem("Cell")
    ---@type UIActivityTotalTopupCellNode
    local nodeEnv  = CfUtils.GetLuaScr(cellNode, "Game.UI.ActivityMainDialog.UIActivityTotalTopupCellNode")
    local index = index + 1
    local accumulativePay  = self:GetAccumulativePay()
    nodeEnv:Refresh(accumulativePay[index] , index , self:GetPlayerAmount() ,self)
    return cellNode
end

function UIActivityTotalTopupPanel:OnDrawRewards()
    GameUtils.Request(Interfaces.ActivityOneKeyDrawAccumulativePayy,
            {rewardId = 0 , activityUuid = self.activityDt.id },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    local data = response.data 
                    local rewards = data.rewards  
                    GoodsUtils.DrawRewards(checkTable(rewards), true)
                    UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = data.rewards }
                        }
                    )
                    self:Refresh(self.activityDt)
                    
                end
    end)
end

function UIActivityTotalTopupPanel:UpdateRedPoint()
    local isOpenRedPoint   = false
    local rechargeTaskList = checkTable(self:GetAccumulativePay())
    for _, listData in ipairs(rechargeTaskList) do
        if checkInt(listData.status) == Constants.GetStatus.Can then
            isOpenRedPoint = true
            break
        end
    end
    ActivityUtils.UpdateActivityMainRedPointState(self.activityDt.id, isOpenRedPoint and 0 or -1)
end

return UIActivityTotalTopupPanel